from pathlib import Path
from math import sin,cos,pi
import subprocess as sp
out=Path.cwd()
work=Path(__file__).parent
ink='#173e35'; muted='#47645a'; pale='#dbe4db'; sun='#e6ac47'; paper='#fffdf6'; green='#21614e'
def rect(x,y,w,h,c):return f'<rect x=\"{x}\" y=\"{y}\" width=\"{w}\" height=\"{h}\" fill=\"{c}\"/>'
def line(x,y,a,b,c=ink,s=1):return f'<path d=\"M{x} {y} L{a} {b}\" stroke=\"{c}\" stroke-width=\"{s}\" fill=\"none\"/>'
def txt(x,y,t,size=16,bold=False,font='Arial',c=ink):return f'<text x=\"{x}\" y=\"{y}\" font-family=\"{font}\" font-size=\"{size}\" font-weight=\"{700 if bold else 400}\" fill=\"{c}\">{t}</text>'
def path(d,fill='none',stroke=ink,s=2):return f'<path d=\"{d}\" fill=\"{fill}\" stroke=\"{stroke}\" stroke-width=\"{s}\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>'
def circle(x,y,r,f,stroke='none',s=1):return f'<circle cx=\"{x}\" cy=\"{y}\" r=\"{r}\" fill=\"{f}\" stroke=\"{stroke}\" stroke-width=\"{s}\"/>'
def group(x,y,k,v):return f'<g transform=\"translate({x} {y}) scale({k})\">{v}</g>'
def gate():
 v=path('M0 48 V21 A23 23 0 0 1 46 21 V48 Z',pale)+path('M8 48 V21 A15 15 0 0 1 38 21 V48 Z',paper)
 for x in [13,20,27,34]:v+=line(x,20,x,47)
 return v+line(8,31,38,31)+line(-4,49,50,49)
def tree():
 v=path('M23 49 L24 28 L15 18 L26 25 L34 14 L29 30 L30 49Z',ink)
 for x,y,r in [(13,20,12),(25,12,13),(38,20,12),(28,23,13)]:v+=circle(x,y,r,green)
 for x,y in [(10,18),(20,11),(31,16),(39,21),(22,25)]:v+=path(f'M{x} {y} q3 -4 6 -4 q-1 5 -6 4',pale,'none')
 return v+line(7,50,46,50)
def wall():
 v=rect(0,14,54,34,pale)
 for y in (14,25,36,48):v+=line(0,y,54,y)
 for row,y in enumerate([14,25,36]):
  for x in ([0,18,36,54] if row%2==0 else [0,9,27,45,54]):v+=line(x,y,x,y+11)
 return v+line(-3,49,58,49)
def bench():
 return path('M4 16 L54 16 L51 25 L1 25Z',pale)+path('M0 29 L50 29 L58 34 L8 34Z',green)+path('M9 35 L7 46 M48 35 L51 46 M10 25 L9 29 M45 25 L44 29',s=3)+line(6,20,51,20)+path('M20 28 L25 21 L33 23 L40 22 L34 29 L28 30Z',paper)+line(33,23,28,30)
def page(title,headline,desc,art):
 return ('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"297mm\" height=\"420mm\" viewBox=\"0 0 600 848\">'+rect(0,0,600,848,paper)+line(28,30,572,30,ink,2)+txt(28,53,'COURTYARD  /  READING BENCH',13,True)+txt(410,53,title,13,True)+txt(28,120,headline,54,False,'Georgia')+txt(30,156,desc,19)+art)
def footer(v):return line(28,792,572,792)+txt(28,818,v,14,False,c=muted)
rows=['Gate alcove','Fig tree','West wall']
data=[[80,25,10],[35,70,85],[15,20,75]]
a=page('SHADE SURVEY','Where’s the shade?','Fictional observations from one clear June day.','')
a+=rect(28,194,544,46,ink)+txt(42,224,'Shaded share of each location',20,True,c=paper)
for x,s in zip([194,329,463],['9 a.m.','Noon','4 p.m.']):a+=txt(x,280,s,23,True)
for i,(name,g) in enumerate(zip(rows,[gate(),tree(),wall()])):
 y=299+114*i
 a+=line(28,y,572,y,muted)+group(34,y+13,.94,g)+txt(32,y+91,name,20,True)
 for j,val in enumerate(data[i]):
  x=[194,329,463][j]
  a+=txt(x,y+56,str(val)+'%',34,False,'Georgia')+rect(x,y+73,103,12,pale)+rect(x,y+73,103*val/100,12,green)
a+=line(28,641,572,641,muted)+rect(28,674,5,84,sun)+txt(47,698,'Most shade at each check',21,True)+txt(47,727,'The gate alcove led at 9 a.m. The fig tree led',20)+txt(47,753,'at noon and again at 4 p.m.',20)+footer('Each full bar represents 100% of that location’s area.')
b=page('RESIDENT VOTE','Pick a bench spot','For the movable reading bench, which spot would you choose?', '') 
b+=rect(28,185,544,80,'#f5e6c8')+group(42,190,1.2,bench())+txt(132,219,'Put one X in an empty circle',24,True)+txt(132,246,'beside your choice. One vote per resident.',18)
for i,name in enumerate(rows):
 y=294+144*i
 b+=line(28,y,572,y,muted)+txt(31,y+37,name,29,False,'Georgia')
 for r in range(2):
  for j in range(19): b+=circle(44+j*28,y+70+29*r,9.8,'white','#758c80',1.2)
b+=line(28,726,572,726,muted)+txt(29,763,'Voting closes',20,True)+line(168,764,440,764)+footer('Two-week resident vote   /   Please leave the pencil here.')
for n,v in [('shade',a),('vote',b)]:
 f=work/(n+'.svg');f.write_text(v+'</svg>');sp.run(['rsvg-convert','-f','pdf','-o',str(work/(n+'.pdf')),str(f)],check=True)
sp.run(['pdfunite',str(work/'shade.pdf'),str(work/'vote.pdf'),str(out/'Courtyard bench exhibit.pdf')],check=True)
